-- Local enabling candidate; requires exact-source synthetic acceptance before publication.
-- Retained history remains readable without asserting that its source is still current.
create function invoice_source_historical_visible(org text,legal text,line invoice_draft_lines,who uuid,held_role text) returns boolean language sql stable as $$
 select case line.source_type when 'TM_SNAPSHOT' then tm_billing_worker_visible(org,legal,line.snapshot_id,who,held_role) when 'MILESTONE_ACCEPTANCE' then exists(select 1 from invoice_draft_batches b where b.id=line.batch_id and b.organization_id=org and b.legal_entity_id=legal and b.source_type=line.source_type and milestone_billing_actor_valid(org,legal,who,held_role,'viewer')) else false end
$$;
create or replace function guard_invoice_batch_review_invalidation() returns trigger language plpgsql as $$
declare ctx jsonb;i invoice_batch_approval_instances;b invoice_draft_batches;line invoice_draft_lines;worker_id text;allow_cancel boolean;allow_withdraw boolean;begin
 begin ctx=nullif(current_setting('workos.invoice_batch_approval_context',true),'')::jsonb;exception when others then ctx=null;end;
 select * into i from invoice_batch_approval_instances where id=new.instance_id;select * into b from invoice_draft_batches where id=i.batch_id for update;perform lock_commercial_candidate_identity(i.organization_id,i.legal_entity_id,new.actor_id,new.active_role);
 allow_cancel=invoice_draft_actor_valid(i.organization_id,i.legal_entity_id,new.actor_id,new.active_role,'cancel');allow_withdraw=new.actor_id=i.requester_user_id and new.active_role=i.active_role and invoice_batch_approval_actor_valid(i.organization_id,i.legal_entity_id,new.actor_id,new.active_role,'submitter');
 if ctx is null or i.id is null or b.id is null or new.id::text is distinct from ctx->>'invalidationId' or i.id::text is distinct from ctx->>'instanceId' or i.batch_id::text is distinct from ctx->>'batchId' or i.organization_id is distinct from ctx->>'organizationId' or i.legal_entity_id is distinct from ctx->>'legalEntityId' or new.actor_id::text is distinct from ctx->>'actorId' or new.active_role is distinct from ctx->>'activeRole' or new.operation_id is distinct from ctx->>'operationId' or not(allow_cancel or allow_withdraw) or invoice_batch_governed_state(b.id)<>'Under Review' or i.sequence<>(select max(x.sequence) from invoice_batch_approval_instances x where x.batch_id=b.id) then raise exception 'Only the active protected review may be withdrawn or cancelled.' using errcode='IBA02';end if;
 for line in select * from invoice_draft_lines where batch_id=b.id order by sequence loop
  if line.source_type='TM_SNAPSHOT' then
   perform lock_tm_billing_worker_witness(i.organization_id,i.legal_entity_id,line.snapshot_id,new.actor_id,new.active_role);
   select h.employee_id into worker_id from commercial_tm_valuations v join work_submission_evidence e on e.id=v.submission_id join timesheets h on h.id=e.timesheet_id where v.id=line.snapshot_id;
   if not invoice_historical_worker_visible(i.organization_id,i.legal_entity_id,worker_id,new.actor_id,new.active_role) then raise exception 'Historical worker scope is required for every retained line.' using errcode='IBA01';end if;
  elsif line.source_type='MILESTONE_ACCEPTANCE' then
   if not invoice_source_historical_visible(i.organization_id,i.legal_entity_id,line,new.actor_id,new.active_role) then raise exception 'Current milestone history access is required.' using errcode='IBA01';end if;
  else raise exception 'Unsupported invoice source.' using errcode='IBA01';end if;
 end loop;return new;
end $$;

create or replace function complete_invoice_batch_invalidation() returns trigger language plpgsql as $$
declare i invoice_batch_approval_instances;begin
 select * into i from invoice_batch_approval_instances where id=new.instance_id;
 if i.id is null or not(invoice_draft_actor_valid(i.organization_id,i.legal_entity_id,new.actor_id,new.active_role,'cancel') or(new.actor_id=i.requester_user_id and new.active_role=i.active_role and invoice_batch_approval_actor_valid(i.organization_id,i.legal_entity_id,new.actor_id,new.active_role,'submitter'))) or exists(select 1 from invoice_draft_lines l join commercial_tm_valuations v on v.id=l.snapshot_id join work_submission_evidence e on e.id=v.submission_id join timesheets h on h.id=e.timesheet_id where l.batch_id=i.batch_id and not invoice_historical_worker_visible(i.organization_id,i.legal_entity_id,h.employee_id,new.actor_id,new.active_role)) or exists(select 1 from invoice_draft_lines l where l.batch_id=i.batch_id and l.source_type='MILESTONE_ACCEPTANCE' and not invoice_source_historical_visible(i.organization_id,i.legal_entity_id,l,new.actor_id,new.active_role)) or not exists(select 1 from approval_records a where a.entity_type='InvoiceBatchApproval' and a.entity_id=i.id::text and a.status='Cancelled') or not exists(select 1 from audit_logs a where a.organization_id=i.organization_id and a.legal_entity_id=i.legal_entity_id and a.user_id=new.actor_id::text and a.active_role=new.active_role and a.module='Invoice Batch Approval' and a.action='Cancel Review' and a.entity_id=new.id::text and a.operation_id=new.operation_id and a.new_value=jsonb_build_object('invalidationId',new.id,'instanceId',i.id,'batchId',i.batch_id)) then raise exception 'Review invalidation, authority and audit must commit together.' using errcode='IBA03';end if;return null;
end $$;

create or replace function guard_invoice_export_notice_recovery() returns trigger language plpgsql as $$
declare ctx jsonb;b invoice_draft_batches;ev invoice_export_notice_events;f invoice_export_notice_producer_failures;begin
 begin ctx=nullif(current_setting('workos.invoice_notice_recovery_context',true),'')::jsonb;exception when others then ctx=null;end;
 select * into b from invoice_draft_batches where id=new.batch_id for update;perform lock_commercial_candidate_identity(new.organization_id,new.legal_entity_id,new.actor_id,new.active_role);
 if ctx is null or b.id is null or new.id::text is distinct from ctx->>'recoveryId' or new.actor_id::text is distinct from ctx->>'actorId' or new.active_role is distinct from ctx->>'activeRole' or new.operation_id is distinct from ctx->>'operationId' or new.organization_id is distinct from ctx->>'organizationId' or new.legal_entity_id is distinct from ctx->>'legalEntityId' or b.organization_id<>new.organization_id or b.legal_entity_id<>new.legal_entity_id or not invoice_csv_actor_valid(new.organization_id,new.legal_entity_id,new.actor_id,new.active_role,'view') or not invoice_notice_actor_has(new.organization_id,new.legal_entity_id,new.actor_id,new.active_role,'commercial.invoice_export.recover_notices') or exists(select 1 from invoice_draft_lines l where l.batch_id=b.id and not invoice_source_historical_visible(b.organization_id,b.legal_entity_id,l,new.actor_id,new.active_role)) then raise exception 'Current scoped notice recovery authority is required.' using errcode='INC01';end if;
 if new.event_id is not null then select * into ev from invoice_export_notice_events where id=new.event_id;if ev.id is null or ev.batch_id<>b.id or ev.policy_id<>new.policy_id or not exists(select 1 from invoice_export_notice_failures where event_id=ev.id) then raise exception 'An incomplete retained event is required.' using errcode='INC02';end if;
 else select * into f from invoice_export_notice_producer_failures where id=new.producer_failure_id;if f.id is null or f.batch_id<>b.id or f.policy_id<>new.policy_id or exists(select 1 from invoice_export_notice_events e where (f.artifact_id is not null and e.artifact_id=f.artifact_id) or (f.failure_id is not null and e.failure_id=f.failure_id) or (f.confirmation_id is not null and e.confirmation_id=f.confirmation_id)) then raise exception 'An incomplete retained event operation is required.' using errcode='INC02';end if;end if;
 return new;
end $$;

create or replace function complete_invoice_export_notice_recovery() returns trigger language plpgsql as $$
declare ev invoice_export_notice_events;f invoice_export_notice_producer_failures;expected integer;actual integer;begin
 if not invoice_csv_actor_valid(new.organization_id,new.legal_entity_id,new.actor_id,new.active_role,'view') or not invoice_notice_actor_has(new.organization_id,new.legal_entity_id,new.actor_id,new.active_role,'commercial.invoice_export.recover_notices') or exists(select 1 from invoice_draft_lines l where l.batch_id=new.batch_id and not invoice_source_historical_visible(new.organization_id,new.legal_entity_id,l,new.actor_id,new.active_role)) or not exists(select 1 from audit_logs a where a.organization_id=new.organization_id and a.legal_entity_id=new.legal_entity_id and a.user_id=new.actor_id::text and a.active_role=new.active_role and a.module='Invoice Export Notifications' and a.action='Attempt Notice Recovery' and a.entity_id=new.id::text and a.operation_id=new.operation_id and a.new_value=jsonb_build_object('recoveryId',new.id,'batchId',new.batch_id,'eventId',new.event_id,'producerFailureId',new.producer_failure_id)) then raise exception 'Recovery authority and sanitized audit must persist through commit.' using errcode='INC03';end if;
 if new.event_id is not null then select * into ev from invoice_export_notice_events where id=new.event_id;else select * into f from invoice_export_notice_producer_failures where id=new.producer_failure_id;select * into ev from invoice_export_notice_events where (f.artifact_id is not null and artifact_id=f.artifact_id) or (f.failure_id is not null and failure_id=f.failure_id) or (f.confirmation_id is not null and confirmation_id=f.confirmation_id);end if;
 if ev.id is not null then select count(distinct recipient)::int into expected from invoice_export_expected_recipients(ev);select count(*)::int into actual from invoice_export_notice_recipients where event_id=ev.id;if actual not in(0,expected) or exists(select 1 from invoice_export_notice_recipients r where r.event_id=ev.id and r.in_app and not exists(select 1 from invoice_export_notice_deliveries d where d.recipient_id=r.id and d.status='Delivered')) then raise exception 'Recovery cannot commit a partial recipient set.' using errcode='INC03';end if;end if;return null;
end $$;

create or replace function guard_invoice_notice_configuration() returns trigger language plpgsql as $$
declare ctx jsonb;last_route invoice_alert_route_versions;last_policy invoice_export_notice_policies;begin
 begin ctx=nullif(current_setting('workos.invoice_notice_context',true),'')::jsonb;exception when others then ctx=null;end;
 perform lock_commercial_candidate_identity(new.organization_id,new.legal_entity_id,new.actor_id,new.active_role);
 if ctx is null or new.id::text is distinct from ctx->>'recordId' or new.organization_id is distinct from ctx->>'organizationId' or new.legal_entity_id is distinct from ctx->>'legalEntityId' or new.actor_id::text is distinct from ctx->>'actorId' or new.active_role is distinct from ctx->>'activeRole' or new.operation_id is distinct from ctx->>'operationId' then raise exception 'Use the exact authenticated scoped configuration command.' using errcode='INC01';end if;
 if tg_table_name='invoice_alert_route_versions' then
  if not invoice_notice_actor_has(new.organization_id,new.legal_entity_id,new.actor_id,new.active_role,'integrations.invoice_alert_routes.manage') then raise exception 'Current scoped alert-route management authority required.' using errcode='INC01';end if;
  perform pg_advisory_xact_lock(hashtext('invoice-alert-route:'||new.organization_id||':'||new.legal_entity_id||':'||new.route_key::text));select * into last_route from invoice_alert_route_versions where organization_id=new.organization_id and legal_entity_id=new.legal_entity_id and route_key=new.route_key order by sequence desc limit 1;
  if new.sequence<>coalesce(last_route.sequence,0)+1 or new.previous_id is distinct from last_route.id then raise exception 'Alert-route version changed.' using errcode='INC02';end if;
 else
  if not invoice_csv_actor_valid(new.organization_id,new.legal_entity_id,new.actor_id,new.active_role,'view') or not invoice_notice_actor_has(new.organization_id,new.legal_entity_id,new.actor_id,new.active_role,'commercial.invoice_export.configure') or not invoice_notice_named_recipient(new.organization_id,new.legal_entity_id,new.finance_owner_id,new.finance_owner_role) or not invoice_draft_actor_valid(new.organization_id,new.legal_entity_id,new.finance_owner_id,new.finance_owner_role,'view') or not invoice_notice_named_recipient(new.organization_id,new.legal_entity_id,new.integration_admin_id,new.integration_admin_role) or not invoice_alert_route_current(new.route_id,new.organization_id,new.legal_entity_id) then raise exception 'Current scoped configuration, recipients and route are required.' using errcode='INC01';end if;
  perform lock_commercial_candidate_identity(new.organization_id,new.legal_entity_id,new.finance_owner_id,new.finance_owner_role);perform lock_commercial_candidate_identity(new.organization_id,new.legal_entity_id,new.integration_admin_id,new.integration_admin_role);perform pg_advisory_xact_lock(hashtext('invoice-notice-policy:'||new.organization_id||':'||new.legal_entity_id||':'||new.engagement_id));select * into last_policy from invoice_export_notice_policies where organization_id=new.organization_id and legal_entity_id=new.legal_entity_id and engagement_id=new.engagement_id order by sequence desc limit 1;
  if new.sequence<>coalesce(last_policy.sequence,0)+1 or new.previous_id is distinct from last_policy.id or new.effective_from<(clock_timestamp() at time zone 'UTC')::date or new.definition->>'engagementId'<>new.engagement_id or new.definition->>'alertRouteId'<>new.route_id::text or new.definition->'financeOwner'<>jsonb_build_object('userId',new.finance_owner_id::text,'role',new.finance_owner_role) or new.definition->'integrationAdmin'<>jsonb_build_object('userId',new.integration_admin_id::text,'role',new.integration_admin_role) then raise exception 'Prospective policy version or named configuration changed.' using errcode='INC02';end if;
 end if;if tg_table_name='invoice_export_notice_policies' then if exists(select 1 from commercial_engagements e where e.organization_id=new.organization_id and e.legal_entity_id=new.legal_entity_id and e.id=new.engagement_id and e.model='milestone') and (not milestone_billing_actor_valid(new.organization_id,new.legal_entity_id,new.actor_id,new.active_role,'viewer') or not milestone_billing_actor_valid(new.organization_id,new.legal_entity_id,new.finance_owner_id,new.finance_owner_role,'viewer')) then raise exception 'Current milestone actor and finance owner access required.' using errcode='INC01';end if;end if;return new;
end $$;

create or replace function complete_invoice_notice_configuration() returns trigger language plpgsql as $$
declare action_name text;expected jsonb;begin
 if tg_table_name='invoice_alert_route_versions' then
  if not invoice_notice_actor_has(new.organization_id,new.legal_entity_id,new.actor_id,new.active_role,'integrations.invoice_alert_routes.manage') then raise exception 'Alert-route authority changed.' using errcode='INC03';end if;
  action_name='Configure Alert Route';expected=jsonb_build_object('routeId',new.id,'routeKey',new.route_key);
 else
  if not invoice_csv_actor_valid(new.organization_id,new.legal_entity_id,new.actor_id,new.active_role,'view') or not invoice_notice_actor_has(new.organization_id,new.legal_entity_id,new.actor_id,new.active_role,'commercial.invoice_export.configure') or not invoice_notice_named_recipient(new.organization_id,new.legal_entity_id,new.finance_owner_id,new.finance_owner_role) or not invoice_draft_actor_valid(new.organization_id,new.legal_entity_id,new.finance_owner_id,new.finance_owner_role,'view') or not invoice_notice_named_recipient(new.organization_id,new.legal_entity_id,new.integration_admin_id,new.integration_admin_role) or not invoice_alert_route_current(new.route_id,new.organization_id,new.legal_entity_id) then raise exception 'Policy authority, route or recipients changed.' using errcode='INC03';end if;
  action_name='Configure Invoice Notification';expected=jsonb_build_object('policyId',new.id,'engagementId',new.engagement_id,'routeId',new.route_id);
 end if;
 if tg_table_name='invoice_export_notice_policies' then if exists(select 1 from commercial_engagements e where e.organization_id=new.organization_id and e.legal_entity_id=new.legal_entity_id and e.id=new.engagement_id and e.model='milestone') and (not milestone_billing_actor_valid(new.organization_id,new.legal_entity_id,new.actor_id,new.active_role,'viewer') or not milestone_billing_actor_valid(new.organization_id,new.legal_entity_id,new.finance_owner_id,new.finance_owner_role,'viewer')) then raise exception 'Milestone actor and finance owner must remain authorized.' using errcode='INC03';end if;end if;
 if not exists(select 1 from audit_logs a where a.organization_id=new.organization_id and a.legal_entity_id=new.legal_entity_id and a.user_id=new.actor_id::text and a.active_role=new.active_role and a.module='Invoice Export Notifications' and a.action=action_name and a.entity_id=new.id::text and a.operation_id=new.operation_id and a.new_value=expected) then raise exception 'Configuration and sanitized audit must commit together.' using errcode='INC03';end if;return null;
end $$;
